mapper.select:
SELECT h.id, h.permit_no, h.address, h.community, h.lat, h.lng, h.stage, h.cover_photo_id,
       h.source_type, h.source_url, h.source_fetched_at, h.created_at,
       h.created_business_date, h.created_by, h.updated_at, p.last_photo_business_date
FROM house h
LEFT JOIN (
    SELECT house_id, MAX(business_date) AS last_photo_business_date
    FROM photo GROUP BY house_id
) p ON p.house_id = h.id


        AND h.lat IS NOT NULL AND h.lng IS NOT NULL
        AND h.lng BETWEEN #{query.minLng} AND #{query.maxLng}
        AND h.lat BETWEEN #{query.minLat} AND #{query.maxLat}


        AND h.stage = #{query.stage}


ORDER BY h.id ASC

mapper.update:
UPDATE house
SET cover_photo_id = #{photoId}, updated_at = GREATEST(updated_at, #{updatedAt})
WHERE id = #{id}

UPDATE house
SET stage = #{toStage}, updated_at = GREATEST(updated_at, #{updatedAt})
WHERE id = #{id} AND stage = #{fromStage}
